dashboard.definition:
{
    "title": "Buttercup Games",
    "description": "A dashboard for the SPL2-based buttercupgames sample app",
    "inputs": {
        "input_global_trp": {
            "options": {
                "defaultValue": "-24h@h,now",
                "token": "global_time"
            },
            "title": "Global Time Range",
            "type": "input.timerange"
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            },
            "ds.spl2": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "visualizations": {
        "viz_8lKv38OB": {
            "options": {
                "preserveAspectRatio": true,
                "src": "splunk-enterprise-kvstore://663b239b7d6be4b096018100"
            },
            "type": "splunk.image"
        },
        "viz_UxGZz4fq": {
            "dataSources": {
                "primary": "ds_LXiydlhH"
            },
            "options": {
                "collapseThreshold": 0.1,
                "labelDisplay": "valuesAndPercentage"
            },
            "title": "Products sold",
            "type": "splunk.pie"
        },
        "viz_ZedUgtjp": {
            "dataSources": {
                "fieldsummary": "ds_NSFJ4c4f",
                "primary": "ds_d7YzF3J2"
            },
            "description": "Expand a metric to see the fields",
            "options": {
                "list.drilldown": "none"
            },
            "title": "From the metrics.log file",
            "type": "splunk.events"
        },
        "viz_ggYjYrfK": {
            "dataSources": {
                "primary": "ds_MFCoBPpk"
            },
            "options": {
                "count": 100,
                "dataOverlayMode": "none",
                "drilldown": "none",
                "showInternalFields": false,
                "showRowNumbers": false
            },
            "title": "Successful purchases",
            "type": "splunk.table"
        },
        "viz_iB77zEua": {
            "context": {
                "convertedColorRange": [
                    {
                        "from": 100,
                        "value": "#dc4e41"
                    },
                    {
                        "from": 70,
                        "to": 100,
                        "value": "#f1813f"
                    },
                    {
                        "from": 30,
                        "to": 70,
                        "value": "#f8be34"
                    },
                    {
                        "from": 0,
                        "to": 30,
                        "value": "#0877a6"
                    },
                    {
                        "to": 0,
                        "value": "#53a051"
                    }
                ]
            },
            "dataSources": {
                "primary": "ds_S4Oq1rT3"
            },
            "description": "Errors from  the _internal index",
            "options": {
                "majorColor": "#f1813f",
                "majorFontSize": 60,
                "numberPrecision": 0,
                "shouldUseThousandSeparators": true,
                "sparklineDisplay": "below",
                "trendDisplay": "absolute",
                "unitPosition": "after"
            },
            "title": "Number of Errors",
            "type": "splunk.singlevalue"
        }
    },
    "dataSources": {
        "ds_LXiydlhH": {
            "name": "Pie chart search",
            "options": {
                "query": "from products | fields product_name, quantity"
            },
            "type": "ds.spl2"
        },
        "ds_MFCoBPpk": {
            "name": "Table search",
            "options": {
                "query": "from successful_purchases"
            },
            "type": "ds.spl2"
        },
        "ds_NSFJ4c4f": {
            "name": "Events 2 Search",
            "options": {
                "query": "from metrics | fieldsummary maxvals=10"
            },
            "type": "ds.spl2"
        },
        "ds_S4Oq1rT3": {
            "name": "Single value search",
            "options": {
                "query": "from error_count"
            },
            "type": "ds.spl2"
        },
        "ds_d7YzF3J2": {
            "name": "Events 1 search",
            "options": {
                "query": "from metrics"
            },
            "type": "ds.spl2"
        }
    },
    "layout": {
        "globalInputs": [
            "input_global_trp"
        ],
        "layoutDefinitions": {
            "layout_1": {
                "options": {
                    "backgroundColor": "#f0d75d",
                    "height": 960,
                    "width": 1440
                },
                "structure": [
                    {
                        "item": "viz_iB77zEua",
                        "position": {
                            "h": 270,
                            "w": 610,
                            "x": 810,
                            "y": 20
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_UxGZz4fq",
                        "position": {
                            "h": 380,
                            "w": 610,
                            "x": 20,
                            "y": 20
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_ggYjYrfK",
                        "position": {
                            "h": 410,
                            "w": 610,
                            "x": 20,
                            "y": 420
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_ZedUgtjp",
                        "position": {
                            "h": 510,
                            "w": 770,
                            "x": 640,
                            "y": 320
                        },
                        "type": "block"
                    },
                    {
                        "item": "viz_8lKv38OB",
                        "position": {
                            "h": 130,
                            "w": 130,
                            "x": 660,
                            "y": 30
                        },
                        "type": "block"
                    }
                ],
                "type": "absolute"
            }
        },
        "tabs": {
            "items": [
                {
                    "label": "New tab",
                    "layoutId": "layout_1"
                }
            ]
        }
    },
    "applicationProperties": {
        "hideEdit": false,
        "hideExport": false,
        "hideOpenInSearch": false
    }
}
